USE EcommerceSalesProject

-- Customer-wise sales - Calculate total sales value generated by each customer.
SELECT 
	c.CustomerID,
	c.CustomerName,
	SUM(od.Quantity * od.UnitPrice) TotalSales
FROM Customers c 
INNER JOIN Orders o 
ON c.CustomerID = o.CustomerID
INNER JOIN OrderDetails od
ON od.OrderID = o.OrderID
WHERE o.Status <> 'Cancelled'
GROUP BY c.CustomerID,c.CustomerName
ORDER BY TotalSales DESC;

-- Top 5 customers - Who are the five most valuable customers based on sales?
SELECT TOP 5
	c.CustomerID,
	c.CustomerName,
	SUM(od.Quantity * od.UnitPrice) TotalSales
FROM Customers c 
INNER JOIN Orders o 
ON c.CustomerID = o.CustomerID
INNER JOIN OrderDetails od
ON od.OrderID = o.OrderID
WHERE o.Status <> 'Cancelled'
GROUP BY c.CustomerID,c.CustomerName
ORDER BY TotalSales DESC;

-- Customer order frequency - Which customers place the most orders?
SELECT 
	c.CustomerID,
	c.CustomerName,
	COUNT(DISTINCT od.OrderID)TotalOrders
FROM Customers c 
INNER JOIN Orders o 
ON c.CustomerID = o.CustomerID
INNER JOIN OrderDetails od
ON od.OrderID = o.OrderID
WHERE o.Status <> 'Cancelled'
GROUP BY c.CustomerID,c.CustomerName
ORDER BY TotalOrders DESC;

-- Average order value per customer - How much does each customer spend on average per order?
SELECT
	CustomerID,
	CustomerName,
	SUM(Sales) TotalSales, 
	AVG(Sales) AvgSales
FROM (
	SELECT 
		c.CustomerID,
		c.CustomerName,
		o.OrderID,
		SUM(od.Quantity * od.UnitPrice) Sales
	FROM Customers c 
	INNER JOIN Orders o 
	ON c.CustomerID = o.CustomerID
	INNER JOIN OrderDetails od
	ON od.OrderID = o.OrderID
	WHERE o.Status <> 'Cancelled' 
	GROUP BY 
		c.CustomerID,
		c.CustomerName,
		o.OrderID
)t
GROUP BY 
	CustomerID,
	CustomerName;

-- Customers who never placed an order - Which registered customers have never placed an order?
SELECT
	c.CustomerID,
	c.CustomerName
FROM Customers c
LEFT JOIN Orders o
ON c.CustomerID = o.CustomerID
WHERE o.CustomerID IS NULL
 